207	    /**
208	     * Returns the two-digit fiscal-year suffix ({@code '<YY>'}) for the given date: the last two digits of
209	     * the calendar year in which that date's fiscal year (starting 1 July) begins. This is the shared segment
210	     * used by both {@link #fiscalYear(Owner)} and the membership number.
211	     *
212	     * @param date the date whose fiscal-year suffix is computed
213	     * @return the zero-padded two-digit fiscal-year suffix
214	     */
215	    protected String fiscalYearSuffix(LocalDate date) {
216	        return String.format("%02d", fiscalYearStart(date) % 100);
217	    }
218	
219	    /**
220	     * Returns the calendar year in which the fiscal year containing {@code date} starts. The fiscal year
221	     * starts on 1 July, so dates from July onward start their fiscal year in the same calendar year, while
222	     * dates from January to June belong to the fiscal year that started in the previous calendar year.
223	     *
224	     * @param date the date whose fiscal-year start is computed
225	     * @return the calendar year in which the containing fiscal year starts
226	     */
227	    protected int fiscalYearStart(LocalDate date) {
228	        int year = date.getYear();
229	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? year : year - 1;
230	    }
231	
232	    /**
233	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits contained in
234	     * the owner's {@code customerCode}. Non-digit characters (such as the letters and dashes in the code) are
235	     * skipped; the rightmost digit is doubled and every second digit thereafter, digits exceeding 9 after
236	     * doubling have 9 subtracted, and the check digit is {@code (10 - sum % 10) % 10}.
237	     *
238	     * @param owner the owner whose check digit is being computed
239	     * @return the Luhn check digit (between 0 and 9 inclusive) over the customer code's digits
240	     */
241	    protected Integer checkDigit(Owner owner) {
242	        String code = owner.getCustomerCode() == null ? "" : owner.getCustomerCode();
243	        int sum = 0;
244	        boolean dbl = true;
245	        for (int i = code.length() - 1; i >= 0; i--) {
246	            char c = code.charAt(i);
247	            if (c < '0' || c > '9') {
248	                continue;
249	            }
250	            int d = c - '0';
251	            if (dbl) {
252	                d *= 2;
253	                if (d > 9) {
254	                    d -= 9;
255	                }
256	            }
257	            sum += d;
258	            dbl = !dbl;
259	        }
260	        return (10 - (sum % 10)) % 10;
261	    }
262	
263	    /**
264	     * Derives an owner's preferred contact channel at read time: {@code 'EMAIL'} when an email address is
265	     * present, otherwise {@code 'PHONE'}.
266	     *
267	     * @param owner the owner whose contact preference is being computed
268	     * @return {@code 'EMAIL'} when the owner has a non-blank email, otherwise {@code 'PHONE'}
269	     */
270	    protected String contactPreference(Owner owner) {
271	        return (owner.getEmail() != null && !owner.getEmail().isBlank()) ? "EMAIL" : "PHONE";
272	    }
273	
274	    /**
275	     * Derives an owner's age band from {@code birthDate}, measured against {@code registrationDate}: the
276	     * completed years between the two dates place the owner in {@code 'MINOR'} (under 18), {@code 'ADULT'}
277	     * (18 to 64 inclusive) or {@code 'SENIOR'} (65 or over). Returns {@code null} when the owner has no
278	     * {@code birthDate}, so the field is simply absent for owners created without one.
279	     *
280	     * @param owner the owner whose age band is being derived
281	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when no birth date is set
282	     */
283	    protected String ageBand(Owner owner) {
284	        if (owner.getBirthDate() == null) {
285	            return null;
286	        }
287	        LocalDate reference = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
288	        int years = Period.between(owner.getBirthDate(), reference).getYears();
289	        if (years < 18) {
290	            return "MINOR";
291	        }
292	        if (years < 65) {
293	            return "ADULT";
294	        }
295	        return "SENIOR";
296	    }
297	
298	    /**
299	     * Derives an owner's {@code identityKey}: the lower-case hex SHA-256 digest of the normalized telephone,
300	     * the lower-cased email (or an empty string when absent) and the {@link #soundex(String) soundex} of the
301	     * last name, joined by {@code '|'} in that order before hashing. This is the single 64-hex key used for
302	     * duplicate detection, so the value returned here matches the one the create endpoint compares.
303	     *
304	     * @param owner the owner whose identity key is being derived
305	     * @return the owner's identity key, a 64-character lower-case hex SHA-256 digest
306	     */
307	    protected String identityKey(Owner owner) {
308	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
309	        String email = owner.getEmail() == null ? "" : owner.getEmail();
310	        String soundex = soundex(owner.getLastName());
311	        return sha256Hex(telephone + "|" + email + "|" + soundex);
312	    }
313	
314	    /**
315	     * Computes the full lower-case hex SHA-256 digest of the UTF-8 bytes of the given value.
316	     *
317	     * @param value the value to hash
318	     * @return the 64-character lower-case hex SHA-256 digest
319	     */
320	    private String sha256Hex(String value) {
321	        try {
322	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
323	            StringBuilder sb = new StringBuilder(digest.length * 2);
324	            for (byte b : digest) {
325	                sb.append(String.format("%02x", b));
326	            }
327	            return sb.toString();
328	        }
329	        catch (NoSuchAlgorithmException e) {
330	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
331	        }
332	    }
333	
334	    /**
335	     * Computes the American Soundex code of the given value: the retained (upper-cased) first letter
336	     * followed by three digits derived from the remaining consonants, right-padded with zeros or truncated
337	     * to length four. Non-letters are ignored; adjacent letters mapping to the same digit are coded once
338	     * (bridged across {@code 'H'}/{@code 'W'}), and vowels reset the run. A {@code null} or letter-free
339	     * value yields an empty string. This matches the create endpoint's soundex so identity keys agree.
340	     *
341	     * @param value the value (typically a last name) to encode
342	     * @return the four-character Soundex code, or an empty string when there are no letters
343	     */
344	    private String soundex(String value) {
345	        if (value == null) {
346	            return "";
347	        }
348	        String letters = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
349	        if (letters.isEmpty()) {
350	            return "";
351	        }
352	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
353	        char prev = soundexDigit(letters.charAt(0));
354	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
355	            char c = letters.charAt(i);
356	            if (c == 'H' || c == 'W') {
357	                continue;
358	            }
359	            char digit = soundexDigit(c);
360	            if (digit != '0' && digit != prev) {
361	                code.append(digit);
362	            }
363	            prev = digit;
364	        }
365	        while (code.length() < 4) {
366	            code.append('0');
367	        }
368	        return code.toString();
369	    }
370	
371	    private char soundexDigit(char c) {
372	        return switch (c) {
373	            case 'B', 'F', 'P', 'V' -> '1';
374	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
375	            case 'D', 'T' -> '3';
376	            case 'L' -> '4';
377	            case 'M', 'N' -> '5';
378	            case 'R' -> '6';
379	            default -> '0';
380	        };
381	    }
382	
383	    /**
384	     * Formats the owner's stored E.164 {@code telephone} for humans: the country code, a space, then the
385	     * national digits grouped in threes from the left (e.g. {@code '+61412345678'} becomes
386	     * {@code '+61 412 345 678'}). The raw {@code telephone} is left untouched in E.164 form. Values that are
387	     * {@code null} or not in E.164 form (no leading {@code '+'}) are returned unchanged.
388	     * <p>
389	     * The country code is split off using the codes the application recognises: {@code '+1'} (NANP) is a
390	     * single digit and any other number is assumed to carry the default {@code '+61'}-style two-digit code.
391	     *
392	     * @param owner the owner whose telephone is being formatted
393	     * @return the human-formatted telephone, or the raw value when it is {@code null} or not E.164
394	     */
395	    protected String telephoneDisplay(Owner owner) {
396	        String telephone = owner.getTelephone();
397	        if (telephone == null || !telephone.startsWith("+")) {
398	            return telephone;
399	        }
400	        String digits = telephone.substring(1);
401	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
402	        if (digits.length() <= countryCodeLength) {
403	            return telephone;
404	        }
405	        String countryCode = digits.substring(0, countryCodeLength);
406	        String national = digits.substring(countryCodeLength);
407	        StringBuilder grouped = new StringBuilder("+").append(countryCode);
408	        for (int i = 0; i < national.length(); i++) {
409	            if (i % 3 == 0) {
410	                grouped.append(' ');
411	            }
412	            grouped.append(national.charAt(i));
413	        }
414	        return grouped.toString();
415	    }
416	
417	    /**
418	     * Composes the owner's salutation: the {@code title}, a single space and the last name (e.g.
419	     * {@code 'DR Franklin'}) when a non-blank {@code title} was supplied, or just the last name when no
420	     * title was given.
421	     *
422	     * @param owner the owner whose salutation is being composed
423	     * @return {@code '<title> <lastName>'} when a title is present, otherwise the last name alone
424	     */
425	    protected String salutation(Owner owner) {
426	        String title = owner.getTitle();
427	        if (title == null || title.isBlank()) {
428	            return owner.getLastName();
429	        }
430	        return title + " " + owner.getLastName();
431	    }
432	
433	    /**
434	     * Derives an owner's {@code selfLink}: the canonical relative URL of the owner resource, formatted
435	     * {@code '/api/owners/<id>'} from the owner's id. Returns {@code null} when the owner has no id yet.
436	     *
437	     * @param owner the owner whose self link is being derived
438	     * @return the owner's self link, or {@code null} when the owner has no id
439	     */
440	    protected String selfLink(Owner owner) {
441	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
442	    }
443	
444	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
445	        OwnerPageDto ownerPageDto = new OwnerPageDto();
446	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
447	        ownerPageDto.setPage(ownerPage.getNumber());
448	        ownerPageDto.setSize(ownerPage.getSize());
449	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
450	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
451	        return ownerPageDto;
452	    }
453	}
